'use strict';
const pages = [['overview','◫','项目概览'],['connect','↗','接入项目'],['documents','▤','需求资料'],['rules','◇','规则审阅'],['cases','☷','测试用例'],['environment','⌘','环境与绑定'],['runs','▷','测试运行'],['report','▥','缺陷报告'],['settings','⚙','项目设置']];
