const pill=(text,color='gray')=>`<span class="pill ${color}">${text}</span>`;
const button=(text,action,kind='',extra='')=>`<button class="${kind}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,page)=>`<a href="#${page}">${text} ↗</a>`;
let state, timer, toastTimer;
function initial(){return {source:'git',step:1,repo:'https://github.com/example/procurement-web',ref:'main',project:'采购协同平台',subdir:'.',url:'https://staging.example.com',approved:false,answer:'',answerSource:'',rejected:false,caseApproved:false,bound:false,envReady:true,runStatus:'idle',runStep:0,runMode:'business',executedMode:'business',profile:{start:'pnpm start',test:'pnpm test',port:'3000',path:'/health'},retestBuild:'',reportCurrent:false,defect:'待确认',retest:false,uploaded:[],filter:'all'};}
state=initial();
const currentPage=()=>pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'overview';
