const stat=(label,value,unit,note)=>`<div class="stat"><div class="stat-label">${label}<span>↗</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`;
const field=(label,id,value,help='',full=false,type='text')=>`<div class="field ${full?'full':''}"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}"><small>${help}</small></div>`;
